// GET /servicenow-incident-ack?key=...&token=...
// Email scanners and link previewers issue GET requests automatically, so a GET must never
// acknowledge anything. It only renders a confirmation form; the POST below does the real work.
const q = $input.first().json.query || {};
const esc = (s) =>
  String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Acknowledge incident alert</title>
<style>
  body{font-family:system-ui,Segoe UI,Arial,sans-serif;background:#f5f6f8;margin:0;display:flex;min-height:100vh;align-items:center;justify-content:center}
  .card{background:#fff;border-radius:10px;box-shadow:0 2px 12px rgba(0,0,0,.1);padding:28px 32px;max-width:420px;width:90%}
  h1{font-size:20px;margin:0 0 6px} p{color:#444;line-height:1.45} code{background:#eef;padding:2px 6px;border-radius:4px}
  input[type=text]{width:100%;box-sizing:border-box;padding:9px;margin:6px 0 14px;border:1px solid #bbb;border-radius:6px}
  button{background:#c0392b;color:#fff;border:0;border-radius:6px;padding:10px 18px;font-size:15px;cursor:pointer}
</style></head><body><div class="card">
<h1>Acknowledge alert</h1>
<p>Alert <code>${esc(q.key)}</code></p>
<p>Acknowledging stops further reminders and escalation for this incident. It does not resolve the incident.</p>
<form method="POST" action="">
  <input type="hidden" name="key" value="${esc(q.key)}">
  <input type="hidden" name="token" value="${esc(q.token)}">
  <label>Your name (optional)<input type="text" name="name" maxlength="80" autocomplete="name"></label>
  <button type="submit">Acknowledge</button>
</form></div></body></html>`;

return [{ json: { html, status: 200 } }];

// POST body: key, token, name (form-encoded). Validate the shape before it touches the table.
// Read the webhook request by node name: `Config` sits between the webhook and this node.
const item = $('Ack Submitted (POST)').first().json;
const b = item.body || {};
const q = item.query || {};
const key = String(b.key !== undefined ? b.key : q.key || '').trim();
const token = String(b.token !== undefined ? b.token : q.token || '').trim();
const name = String(b.name || '').trim().slice(0, 80) || 'email link';

const validKey = /^[A-Za-z0-9_-]{3,40}:(critical|high|stale)$/.test(key);
const validToken = /^[A-Za-z0-9-]{16,100}$/.test(token);
return [{ json: { key, token, name, valid: validKey && validToken } }];

// Decides the outcome of an acknowledgement request. The token is the per-alert secret stored in
// the row, so the email link only ever works for the alert it was sent for - and a re-opened
// incident gets a new token, so an old link cannot acknowledge the new occurrence.
const req = $('Prepare Ack').first().json;
const cfg = $('Config').first().json;
const rows = $input.all().map((i) => i.json);
const row = rows.find((r) => r && r.dedup_key === req.key && r.ack_token === req.token);

const fail = (status, message) => [{ json: { write: false, ok: false, status, message } }];

if (!req.valid || !row) {
  return fail(404, 'This acknowledgement link is invalid or has expired.');
}
if (row.status === 'resolved') {
  return fail(410, `Alert ${row.dedup_key} is already resolved - there is nothing to acknowledge.`);
}
if (row.acked_at) {
  return [{ json: { write: false, ok: true, status: 200, message: `Alert ${row.dedup_key} was already acknowledged by ${row.acked_by || 'someone'}.` } }];
}

let sysId = '';
try {
  sysId = (JSON.parse(row.payload || '{}') || {}).sysId || '';
} catch (e) {
  sysId = '';
}

return [
  {
    json: {
      write: true,
      ok: true,
      status: 200,
      message: `Alert ${row.dedup_key} acknowledged by ${req.name}. Reminders and escalation are stopped.`,
      dedup_key: row.dedup_key,
      version: Number(row.version) + 1, // bumping `version` makes any in-flight claim of this row lose its CAS
      acked_at: new Date().toISOString(),
      acked_by: req.name,
      ack_source: 'email-link',
      sysId,
      writeBack: Boolean(cfg.writeBack),
    },
  },
];

// Work note written back to the ServiceNow incident (optional - needs write access on `incident`).
const p = $('Apply Ack').first().json;
return [{ json: { sysId: p.sysId, note: `Alert ${p.dedup_key} acknowledged via n8n by ${p.acked_by} at ${p.acked_at}.` } }];

// Builds the HTML page shown after the POST. Reached either straight from "Apply Ack"
// (nothing to write / rejected) or after the table update.
const plan = $('Apply Ack').first().json;
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

let ok = plan.ok;
let status = plan.status;
let message = plan.message;

if (plan.write) {
  // After "Save Acknowledgement": the compare-and-swap returns the row only if it still matched.
  const saved = $('Save Acknowledgement').all().some((i) => i.json && i.json.dedup_key === plan.dedup_key && i.json.acked_at);
  if (!saved) {
    ok = false;
    status = 409;
    message = 'The alert changed while you were acknowledging it. Please click the link in the email again.';
  }
}

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${ok ? 'Acknowledged' : 'Not acknowledged'}</title>
<style>body{font-family:system-ui,Segoe UI,Arial,sans-serif;background:#f5f6f8;margin:0;display:flex;min-height:100vh;align-items:center;justify-content:center}
.card{background:#fff;border-radius:10px;box-shadow:0 2px 12px rgba(0,0,0,.1);padding:28px 32px;max-width:440px;width:90%}
h1{font-size:20px;margin:0 0 8px;color:${ok ? '#1e8449' : '#c0392b'}}p{color:#444;line-height:1.45}</style></head>
<body><div class="card"><h1>${ok ? 'Acknowledged' : 'Not acknowledged'}</h1><p>${esc(message)}</p></div></body></html>`;

return [{ json: { html, status } }];
